namespace {
int checks=0;
const char* guide_ids[]={"guide-x","guide-y"};
const char* sources[]={"10 + 0.5","20 + 0.5"};
void check(bool ok,const char* why){if(!ok)throw std::runtime_error(why);++checks;}
void events(){QApplication::processEvents();QApplication::sendPostedEvents(nullptr,QEvent::DeferredDelete);QTest::qWait(15);}
template<class T>T* control(Window& w,const QString& name){for(auto* c:w.findChildren<T*>(name))if(c->isVisible())return c;throw std::runtime_error(("Missing control: "+name).toStdString());}
QString name(int field,const char* suffix){
 if(QString(suffix)=="-expression")return "guide-position-expression-"+QString(guide_ids[field]);
 if(QString(suffix)=="-apply-expression")return "guide-position-apply-expression-"+QString(guide_ids[field]);
 return "guide-position-"+QString(guide_ids[field]);
}
void reveal(QWidget* c){for(auto* p=c->parentWidget();p;p=p->parentWidget())if(auto* s=qobject_cast<QScrollArea*>(p))s->ensureWidgetVisible(c);events();check(c->isVisible(),"Exact production control visible");}
void valid(const Document& d){validate(d);check(decode(encode(d))==d,"Independent full Document native-valid BEFORE Window");}
Document fixture(int mode){
 auto d=empty_document("guide-prefix-"+std::to_string(mode),"composition","board");auto& comp=d.compositions.front();auto& b=comp.artboards.front();b.width=1200;b.height=900;
 b.layout=ArtboardLayout{Margin{10.123456789012345,20.234567890123456,30.345678901234567,40.456789012345678},Grid{"grid",{15.123456789012345,20.234567890123456,1000.1234567890123,800.23456789012345},3,2,7.345678901234567,8.456789012345678}};
 comp.guides={{"guide-x","Vertical","x",10.123456789012345},{"guide-y","Horizontal","y",20.234567890123456},{"peer","Untouched peer","x",30.345678901234567}};comp.guides[2].position_expression=Expression{"30 + 0.25",1};
 Object o;o.id="sentinel";o.kind=Kind::path;Contour c;c.id="contour";Point p;p.id="point";p.x.literal=51.25;p.y.literal=-21.75;c.points={p};o.contours={c};d.objects.emplace(o.id,o);comp.roots={o.id};valid(d);return d;
}
Document wanted(const Document& initial,int field){auto d=initial;d.compositions.front().guides[field].position_expression=Expression{sources[field],1};valid(d);return d;}
std::vector<Command> command(int field,const char* body=nullptr){return {SetGuidePositionExpression{{guide_ids[field],"","guide.position"},{body?body:sources[field],1},false}};}
Session gesture_commit(const Document& d,int field){Session expected(d);expected.begin_gesture(0);expected.update_gesture(command(field));expected.commit_gesture();return expected;}
void same(const Session& a,const Session& b){if(!(a.document()==b.document()&&a.history()==b.history()&&a.revision()==b.revision()&&a.gesture_active()==b.gesture_active()&&a.gesture_generation()==b.gesture_generation()))std::cerr<<"Snapshot doc="<<(a.document()==b.document())<<" history="<<(a.history()==b.history())<<" rev="<<a.revision()<<"/"<<b.revision()<<" active="<<a.gesture_active()<<"/"<<b.gesture_active()<<" gen="<<a.gesture_generation()<<"/"<<b.gesture_generation()<<"\n";check(a.document()==b.document()&&encode(a.document())==encode(b.document())&&a.preview_document()==b.preview_document()&&a.history()==b.history()&&a.revision()==b.revision()&&a.gesture_active()==b.gesture_active()&&a.gesture_generation()==b.gesture_generation(),"Full canonical Session equals independent pre-Window expectation");}
void write(const QString& path,const Document& d){QFile f(path);const auto bytes=encode(d);check(f.open(QIODevice::WriteOnly|QIODevice::NewOnly)&&f.write(bytes.data(),bytes.size())==static_cast<qint64>(bytes.size()),"Independent native oracle retained once");}
QByteArray read(const QString& path){QFile f(path);check(f.open(QIODevice::ReadOnly),"Owned native bytes readable");return f.readAll();}
QString prefix(const QString& root,int mode){return root+"/mode-"+QString::number(mode);}
void open(Window& w,const Document& d){w.host.session=Session(d);w.host.edited();w.canvas->set_active_artboard("composition","board",false);w.resize(1400,1000);w.show();w.activateWindow();events();auto* dock=w.findChild<QDockWidget*>("properties");check(dock,"Properties exists");dock->show();dock->raise();events();auto* edit=control<QPushButton>(w,"artboard-edit");reveal(edit);edit->click();events();}
void enter_prefix(Window& w,int field,const QString& text){auto* input=control<QLineEdit>(w,"guide-position-"+QString(guide_ids[field]));reveal(input);input->setFocus();QTest::keyClick(input,Qt::Key_A,Qt::ControlModifier);QTest::keyClicks(input,text);events();QTest::keyClick(input,Qt::Key_Return);events();}
void enter_numeric(Window& w,int field,const QString& text,bool commit){auto* input=control<QLineEdit>(w,"guide-position-"+QString(guide_ids[field]));reveal(input);input->setFocus();QTest::keyClick(input,Qt::Key_A,Qt::ControlModifier);QTest::keyClicks(input,text);events();if(commit){QTest::keyClick(input,Qt::Key_Return);events();}}
void cancel(Window& w,int field){auto* editor=control<QPlainTextEdit>(w,name(field,"-expression"));reveal(editor);editor->setFocus();QTest::keyClick(editor,Qt::Key_Escape);events();}
void apply(Window& w,int field){auto* editor=control<QPlainTextEdit>(w,name(field,"-expression"));reveal(editor);editor->setFocus();QTest::keyClick(editor,Qt::Key_Return,Qt::ControlModifier);events();}
void reset(Window& w,const Document& d,const QString& key){w.host.session=Session(d);w.host.session_id+=key;w.host.edited();events();}
void cold(const QString& root,int mode){const auto d=wanted(fixture(mode),mode);Session expected(d);const auto path=prefix(root,mode);QSettings settings(root+"/settings.ini",QSettings::IniFormat);Window w(path+"-cold",std::make_unique<FolderLibrary>(settings),&settings);w.host.open(path+"-cold-input.nect");same(w.host.session,expected);w.host.save(path+"-resaved.nect");w.host.flush();same(w.host.session,expected);check(read(path+"-cold-input.nect")==read(path+"-expected.nect")&&read(path+"-resaved.nect")==read(path+"-expected.nect"),"Separate cold exact expression native bytes");QTest::qWait(120);}


void flow(const QString& root,int mode){
 const int field=mode;const auto initial=fixture(mode),intended=wanted(initial,field);Session before(initial),direct(initial);direct.apply(command(field),0);auto committed=gesture_commit(initial,field);check(direct.document()==intended&&committed.document()==intended&&committed.history()==direct.history(),"Independent full numeric-source handoff authoring and canonical gesture expectation BEFORE Window");
 auto incoming=initial.compositions.front().artboards.front();incoming.name="External revision";Session newer(initial);newer.apply({UpdateArtboard{"composition",incoming}},0);auto newer_intended=intended;newer_intended.compositions.front().artboards.front().name=incoming.name;valid(newer_intended);auto refreshed_commit=newer;refreshed_commit.begin_gesture(1);refreshed_commit.update_gesture(command(field));refreshed_commit.commit_gesture();check(refreshed_commit.document()==newer_intended,"Independent refreshed numeric-source commit BEFORE Window");
 auto replacement=initial;replacement.id+="-replacement";valid(replacement);Session replaced(replacement);auto driven_doc=initial;driven_doc.compositions.front().guides[field].position_expression=Expression{"42",1};valid(driven_doc);Session driven(driven_doc);
 const char* invalid_sources[]={"1 +","1 / 0",""};std::array<Session,3> invalid{before,before,before};std::array<QString,3> invalid_errors;for(int i=0;i<3;++i){invalid[i].begin_gesture(0);try{invalid[i].update_gesture(command(field,invalid_sources[i]));}catch(const Error& e){invalid_errors[i]=QString::fromStdString(e.code);}invalid[i].cancel_gesture();check(!invalid_errors[i].isEmpty()&&invalid[i].document()==initial&&invalid[i].history()==before.history()&&invalid[i].revision()==0&&!invalid[i].gesture_active(),"Independent incomplete/invalid/empty source refusal BEFORE Window");}
 auto numeric_doc=initial;numeric_doc.compositions.front().guides[field].position=field?22.5:12.5;valid(numeric_doc);Session numeric(initial);numeric.begin_gesture(0);numeric.update_gesture({UpdateGuide{"composition",numeric_doc.compositions.front().guides[field]}});auto numeric_preview=numeric;numeric.commit_gesture();check(numeric.document()==numeric_doc,"Independent absolute numeric expectation BEFORE Window");
 auto negative_doc=initial;negative_doc.compositions.front().guides[field].position=-3.25;valid(negative_doc);Session negative(initial);negative.begin_gesture(0);negative.update_gesture({UpdateGuide{"composition",negative_doc.compositions.front().guides[field]}});negative.commit_gesture();check(negative.document()==negative_doc,"Independent negative absolute numeric expectation BEFORE Window");
 auto cancelled=numeric_preview;cancelled.cancel_gesture();auto own_committed=cancelled;own_committed.begin_gesture(0);own_committed.update_gesture(command(field));own_committed.commit_gesture();check(own_committed.document()==intended&&own_committed.history()==committed.history(),"Own numeric preview cancels without authoring before source commit BEFORE Window");
 auto foreign=before;foreign.begin_gesture(0);foreign.update_gesture({UpdateArtboard{"composition",incoming}});auto replacement_generation=cancelled;replacement_generation.begin_gesture(0);replacement_generation.update_gesture({UpdateArtboard{"composition",incoming}});
 const auto path=prefix(root,mode);write(path+"-initial.nect",initial);write(path+"-expected.nect",intended);QSettings settings(root+"/settings.ini",QSettings::IniFormat);Window w(path+"-recovery",std::make_unique<FolderLibrary>(settings),&settings);open(w,initial);same(w.host.session,before);enter_prefix(w,field,"="+QString(sources[field]));same(w.host.session,before);auto* editor=control<QPlainTextEdit>(w,name(field,"-expression"));check(editor->parentWidget()->grab().save(path+"-prefix-draft.png"),"Actual numeric-source handoff row render retained");std::cout<<"PREFIX field="<<field<<" source="<<editor->toPlainText().toStdString()<<" expected="<<sources[field]<<"\n";check(editor->toPlainText()==sources[field],"Existing Guide numeric =expression Return hands exact source body to existing draft without authoring");auto* number=control<QLineEdit>(w,"guide-position-"+QString(guide_ids[field]));check(number->text()==QString::number(initial.compositions.front().guides[field].position,'g',15)&&!number->isModified(),"Source handoff restores original numeric display without zero or pending numeric intent");
 w.host.save(path+"-draft-save.nect");w.host.flush();events();same(w.host.session,before);check(read(path+"-draft-save.nect")==read(path+"-initial.nect"),"Prefix view source excluded from actual native Save");check(control<QPlainTextEdit>(w,name(field,"-expression"))->toPlainText()==sources[field],"Prefix source survives actual Save/processed refresh");apply(w,field);same(w.host.session,committed);w.host.save(path+"-saved.nect");w.host.flush();events();same(w.host.session,committed);check(QFile::copy(path+"-saved.nect",path+"-cold-input.nect"),"Actual prefix committed source retained before later edits");QProcess child;child.start(QCoreApplication::applicationFilePath(),{"--cold",root,QString::number(mode)});check(child.waitForStarted(5000),"Owned cold starts");if(!child.waitForFinished(15000)){child.kill();child.waitForFinished();throw std::runtime_error("Owned cold deadline");}std::cout<<child.readAllStandardOutput().toStdString();std::cerr<<child.readAllStandardError().toStdString();check(child.exitStatus()==QProcess::NormalExit&&child.exitCode()==0,"Separate cold prefix source native acceptance passes");
 w.host.session.undo(w.host.session.revision());committed.undo(committed.revision());w.host.edited();events();same(w.host.session,committed);check(w.host.session.document()==initial,"One Undo restores full source/literal/IDs/siblings/layout/sentinel");w.host.session.redo(w.host.session.revision());committed.redo(committed.revision());w.host.edited();events();same(w.host.session,committed);
 reset(w,initial,"-cancel");enter_prefix(w,field,"="+QString(sources[field]));cancel(w,field);same(w.host.session,before);w.host.edited();events();check(control<QPlainTextEdit>(w,name(field,"-expression"))->toPlainText().isEmpty(),"Escape discards prefix view source and stays cleared");
 for(int i=0;i<3;++i){reset(w,initial,"-invalid-"+QString::number(i));enter_prefix(w,field,"="+QString(invalid_sources[i]));same(w.host.session,before);check(control<QPlainTextEdit>(w,name(field,"-expression"))->toPlainText()==invalid_sources[i],"Incomplete/invalid/bare prefix exact draft never becomes zero");apply(w,field);same(w.host.session,invalid[i]);check(w.statusBar()->currentMessage().contains(invalid_errors[i]),"Existing canonical source Apply refuses invalid prefix body");w.host.edited();events();check(control<QPlainTextEdit>(w,name(field,"-expression"))->toPlainText()==invalid_sources[i],"Refused source remains editable through refresh");}
 reset(w,initial,"-absolute");enter_numeric(w,field,field?"22.5":"12.5",true);same(w.host.session,numeric);reset(w,initial,"-negative");enter_numeric(w,field,"-3.25",true);same(w.host.session,negative);
 reset(w,initial,"-own-preview");enter_numeric(w,field,field?"22.5":"12.5",false);same(w.host.session,numeric_preview);enter_prefix(w,field,"="+QString(sources[field]));same(w.host.session,cancelled);check(control<QPlainTextEdit>(w,name(field,"-expression"))->toPlainText()==sources[field],"Prefix cancels only its own exact numeric preview before source handoff");apply(w,field);same(w.host.session,own_committed);
 reset(w,initial,"-stale-revision");w.host.session.apply({UpdateArtboard{"composition",incoming}},0);enter_prefix(w,field,"="+QString(sources[field]));same(w.host.session,newer);check(w.statusBar()->currentMessage().contains("REVISION_CONFLICT"),"Old numeric control cannot hand source into newer revision");check(control<QPlainTextEdit>(w,name(field,"-expression"))->toPlainText().isEmpty(),"Stale numeric callback cannot create source draft");w.host.edited();events();enter_prefix(w,field,"="+QString(sources[field]));apply(w,field);same(w.host.session,refreshed_commit);
 reset(w,initial,"-retained-original-revision");enter_prefix(w,field,"="+QString(sources[field]));w.host.session.apply({UpdateArtboard{"composition",incoming}},0);w.host.edited();events();enter_prefix(w,field,"="+QString(sources[field]));same(w.host.session,newer);apply(w,field);same(w.host.session,newer);check(w.statusBar()->currentMessage().contains("REVISION_CONFLICT")&&control<QPlainTextEdit>(w,name(field,"-expression"))->toPlainText()==sources[field],"Fresh numeric handoff cannot silently update retained source draft original revision");cancel(w,field);enter_prefix(w,field,"="+QString(sources[field]));apply(w,field);same(w.host.session,refreshed_commit);
 reset(w,initial,"-stale-session");w.host.session_id+="-new";enter_prefix(w,field,"="+QString(sources[field]));same(w.host.session,before);check(w.statusBar()->currentMessage().contains("SESSION_CONFLICT"),"Old numeric source callback refuses replacement Session");check(control<QPlainTextEdit>(w,name(field,"-expression"))->toPlainText().isEmpty(),"Old Session prefix cannot populate source");
 reset(w,initial,"-stale-document");w.host.session=Session(replacement);enter_prefix(w,field,"="+QString(sources[field]));same(w.host.session,replaced);check(w.statusBar()->currentMessage().contains("SESSION_CONFLICT"),"Same Session/revision numeric callback refuses replacement Document");check(control<QPlainTextEdit>(w,name(field,"-expression"))->toPlainText().isEmpty(),"Replacement Document cannot inherit source");
 reset(w,initial,"-driven");reset(w,driven_doc,"-readonly");enter_prefix(w,field,"="+QString(sources[field]));same(w.host.session,driven);check(control<QLineEdit>(w,"guide-position-"+QString(guide_ids[field]))->isReadOnly()&&control<QPlainTextEdit>(w,name(field,"-expression"))->toPlainText()=="42","Driven numeric input cannot silently replace source");
 reset(w,initial,"-foreign");w.host.session.begin_gesture(0);w.host.session.update_gesture({UpdateArtboard{"composition",incoming}});w.host.edited();events();enter_prefix(w,field,"="+QString(sources[field]));same(w.host.session,foreign);check(w.statusBar()->currentMessage().contains("GESTURE_ACTIVE")&&control<QPlainTextEdit>(w,name(field,"-expression"))->toPlainText().isEmpty(),"Prefix refuses foreign gesture without source or caller mutation");w.host.session.cancel_gesture();
 reset(w,initial,"-foreign-generation");enter_numeric(w,field,field?"22.5":"12.5",false);same(w.host.session,numeric_preview);w.host.session.cancel_gesture();w.host.session.begin_gesture(0);w.host.session.update_gesture({UpdateArtboard{"composition",incoming}});enter_prefix(w,field,"="+QString(sources[field]));same(w.host.session,replacement_generation);std::cout<<"GENERATION_REFUSAL field="<<field<<" message="<<w.statusBar()->currentMessage().toStdString()<<" source="<<control<QPlainTextEdit>(w,name(field,"-expression"))->toPlainText().toStdString()<<"\n";check(control<QPlainTextEdit>(w,name(field,"-expression"))->toPlainText().isEmpty(),"Replacement caller generation cannot receive a source draft");const auto refusal=w.statusBar()->currentMessage();check(refusal.contains("REVISION_CONFLICT")||refusal.contains("GESTURE_ACTIVE"),"Old or refreshed view explicitly refuses active replacement caller");w.host.session.cancel_gesture();
}

}
int main(int argc,char** argv){qputenv("QT_QPA_PLATFORM","windows");QApplication app(argc,argv);try{std::cout<<"Native platform="<<QGuiApplication::platformName().toStdString()<<" PID="<<QCoreApplication::applicationPid()<<"\n";if(argc==4&&std::string(argv[1])=="--cold")cold(QString::fromLocal8Bit(argv[2]),std::stoi(argv[3]));else{QTemporaryDir temporary;check(temporary.isValid(),"Owned scratch valid");const auto requested=qEnvironmentVariable("NECT_GUIDE_NUMERIC_PREFIX_ROOT"),root=requested.isEmpty()?temporary.path():requested;int failures=0;for(int mode=0;mode<2;++mode){try{flow(root,mode);std::cout<<"CASE PASS mode="<<mode<<"\n";}catch(const std::exception& e){++failures;std::cerr<<"CASE FAIL mode="<<mode<<" reason="<<e.what()<<" checks="<<checks<<"\n";}}if(failures)throw std::runtime_error("Independent expression key cases failed: "+std::to_string(failures));}std::cout<<"PASS Guide numeric source prefix "<<checks<<" checks\n";return 0;}catch(const std::exception& e){std::cerr<<"FAIL Guide numeric source prefix "<<e.what()<<" after "<<checks<<" checks\n";return 1;}}
